PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE admins (
	admin_id INTEGER,
	name TEXT,
	email TEXT,
	password_hash TEXT,
	enabled INTEGER,
	date_created TEXT, roles TEXT DEFAULT (''),
	CONSTRAINT admins_pk PRIMARY KEY (admin_id)
);
CREATE TABLE admins_aggregate (
	version INTEGER
);
CREATE TABLE admins_roles (
                                admin_id INTEGER,
                                role_id INTEGER
                            );
CREATE TABLE clients (
	client_id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
	admin_id INTEGER,
	client_name TEXT,
	emails TEXT,
	address TEXT,
	enabled INTEGER DEFAULT (1), date_created TEXT, version INTEGER DEFAULT (0), phones TEXT,
	CONSTRAINT clients_admins_FK FOREIGN KEY (admin_id) REFERENCES admins(admin_id)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_admins_name ON admins(name);
CREATE INDEX idx_admins_email ON admins(email);
CREATE INDEX idx_admins_enabled ON admins(enabled);
COMMIT;
